@@ -0,0 +1,22 @@
+// Sites (kitchens). Every location belongs to a site; batches and stock
+// operations belong to the site of their location.
+import { AppError } from "../errors.js";
+
+/** Every site, in store order. */
+export function listSites(store) {
+  return [...(store.data.sites ?? [])];
+}
+
+/** One site, or AppError unknown_site. */
+export function getSite(store, id) {
+  const site = (store.data.sites ?? []).find((s) => s.id === id);
+  if (!site) throw new AppError("unknown_site", { id });
+  return site;
+}
+
+/** Set of location ids in `site`, or null when no site filter is given. */
+export function siteLocationIds(store, site) {
+  if (site === undefined) return null;
+  getSite(store, site);
+  return new Set((store.data.locations ?? []).filter((l) => l.site === site).map((l) => l.id));
+}
