@@ -0,0 +1,191 @@
+import test from "node:test";
+import assert from "node:assert/strict";
+import { readFileSync } from "node:fs";
+import { CURRENT_VERSION, migrate } from "../src/db/migrations.js";
+import { openStore } from "../src/db/store.js";
+import { t } from "../src/i18n/messages.js";
+import { app, seed } from "./helpers.js";
+
+const ANNEX = { "X-Larder-Site": "annex" };
+
+async function receiveAtAnnex(handle, lines, lots) {
+  const created = await handle({ method: "POST", path: "/orders", headers: ANNEX, body: { supplierId: 1, lines } });
+  assert.equal(created.status, 201);
+  await handle({ method: "POST", path: `/orders/${created.body.id}/send`, headers: ANNEX });
+  const received = await handle({ method: "POST", path: `/orders/${created.body.id}/receive`, headers: ANNEX, body: { lots } });
+  assert.equal(received.status, 200);
+  return received.body.batches;
+}
+
+test("schema 3 seed has main and annex sites and locations", () => {
+  const data = seed();
+  assert.equal(data.schemaVersion, 3);
+  assert.deepEqual(data.sites, [
+    { id: "main", name: "Main kitchen" },
+    { id: "annex", name: "Annex kitchen" },
+  ]);
+  assert.ok(data.locations.filter((l) => l.id !== "annex-fridge").every((l) => l.site === "main"));
+  assert.deepEqual(data.locations.find((l) => l.id === "annex-fridge"), {
+    id: "annex-fridge",
+    name: "Annex fridge",
+    tempC: 4,
+    site: "annex",
+  });
+});
+
+test("older schema 1 and schema 2 files migrate to schema 3", () => {
+  const v1 = migrate(JSON.parse(readFileSync(new URL("../data/legacy-v1.json", import.meta.url), "utf8")));
+  assert.equal(v1.schemaVersion, CURRENT_VERSION);
+  assert.deepEqual(v1.sites, [{ id: "main", name: "Main kitchen" }]);
+  assert.ok(v1.locations.every((l) => l.site === "main"));
+
+  const v2Store = openStore(new URL("../data/db.json", import.meta.url).pathname);
+  assert.equal(v2Store.data.schemaVersion, 3);
+  assert.deepEqual(v2Store.data.sites, [{ id: "main", name: "Main kitchen" }]);
+  assert.ok(v2Store.data.locations.every((l) => l.site === "main"));
+});
+
+test("unknown X-Larder-Site returns 400 with unknown_site error code and messages", async () => {
+  const { handle } = app();
+  const res = await handle({ path: "/items", headers: { "X-Larder-Site": "rooftop" } });
+  assert.equal(res.status, 400);
+  assert.equal(res.body.error.code, "unknown_site");
+  assert.match(res.body.error.message, /rooftop/);
+  assert.match(t("unknown_site", "ko", { id: "rooftop" }), /rooftop/);
+});
+
+test("batches, stock on hand, stock value and alerts are isolated per site", async () => {
+  const { handle } = app();
+
+  // Annex starts empty; main has all seed stock.
+  const annexItems0 = (await handle({ path: "/items", headers: ANNEX })).body;
+  assert.equal(annexItems0.length, 6);
+  assert.ok(annexItems0.every((i) => i.onHand === 0));
+  assert.deepEqual((await handle({ path: "/batches", headers: ANNEX })).body, []);
+  assert.equal((await handle({ path: "/batches/1", headers: ANNEX })).status, 404);
+  assert.equal((await handle({ method: "POST", path: "/batches/1/waste", headers: ANNEX, body: { qty: 1 } })).status, 404);
+  assert.equal((await handle({ path: "/reports/stock-value", headers: ANNEX })).body.totalCents, 0);
+
+  const annexAlerts0 = (await handle({ path: "/alerts", headers: ANNEX })).body;
+  assert.deepEqual(annexAlerts0.expiring, []);
+  assert.equal(annexAlerts0.lowStock.length, 6);
+
+  // Receive stock into annex-fridge (soon expiring milk + onions).
+  const [annexBatch1, annexBatch2] = await receiveAtAnnex(
+    handle,
+    [
+      { itemId: 1, qty: 6 },
+      { itemId: 2, qty: 2 },
+    ],
+    [
+      { lot: "AX-ONION", expires: "2026-11-20", location: "annex-fridge" },
+      { lot: "AX-MILK", expires: "2026-10-30", location: "annex-fridge" },
+    ],
+  );
+
+  // Main stock is unaffected.
+  assert.equal((await handle({ path: "/items/1" })).body.onHand, 10);
+  assert.equal((await handle({ path: "/batches" })).body.length, 9);
+  assert.equal((await handle({ path: `/batches/${annexBatch1.id}` })).status, 404);
+
+  // Annex only sees its own batches, stock on hand, stock value, and alerts.
+  const annexOnion = (await handle({ path: "/items/1", headers: { "x-larder-site": "annex" } })).body;
+  assert.equal(annexOnion.onHand, 6);
+  assert.deepEqual(annexOnion.batches.map((b) => b.lot), ["AX-ONION"]);
+
+  const annexVal = (await handle({ path: "/reports/stock-value", headers: ANNEX })).body;
+  assert.equal(annexVal.totalCents, 6 * 180 + 2 * 129);
+
+  const annexAlerts = (await handle({ path: "/alerts", headers: ANNEX })).body;
+  assert.deepEqual(annexAlerts.expiring.map((b) => b.id), [annexBatch2.id]);
+  assert.equal(annexAlerts.lowStock.some((i) => i.itemId === 1), false);
+  assert.equal(annexAlerts.lowStock.some((i) => i.itemId === 2), true);
+
+  // Main alerts do not see annex's expiring batch.
+  const mainAlerts = (await handle({ path: "/alerts" })).body;
+  assert.equal(mainAlerts.expiring.some((b) => b.id === annexBatch2.id), false);
+});
+
+test("cooking only uses batches from the request's site", async () => {
+  const { handle } = app();
+
+  // Annex cannot cook bechamel without its own stock even though main has enough.
+  const fail = await handle({ method: "POST", path: "/recipes/2/cook", headers: ANNEX, body: { portions: 5 } });
+  assert.equal(fail.status, 409);
+  assert.equal(fail.body.error.code, "not_enough_stock");
+
+  // Give annex enough milk (2), butter (3), flour (4) for 5 portions of bechamel (1, 0.1, 0.1).
+  await receiveAtAnnex(
+    handle,
+    [
+      { itemId: 2, qty: 2 },
+      { itemId: 3, qty: 0.5 },
+      { itemId: 4, qty: 1 },
+    ],
+    [
+      { lot: "AX-M", expires: "2026-11-10", location: "annex-fridge" },
+      { lot: "AX-B", expires: "2026-12-10", location: "annex-fridge" },
+      { lot: "AX-F", expires: "2027-01-10", location: "annex-fridge" },
+    ],
+  );
+
+  const mainBefore = (await handle({ path: "/items" })).body.map((i) => [i.id, i.onHand]);
+  const ok = await handle({ method: "POST", path: "/recipes/2/cook", headers: ANNEX, body: { portions: 5 } });
+  assert.equal(ok.status, 200);
+
+  // Annex stock decreased; main stock untouched.
+  assert.equal((await handle({ path: "/items/2", headers: ANNEX })).body.onHand, 1);
+  assert.equal((await handle({ path: "/items/3", headers: ANNEX })).body.onHand, 0.4);
+  assert.equal((await handle({ path: "/items/4", headers: ANNEX })).body.onHand, 0.9);
+  assert.deepEqual((await handle({ path: "/items" })).body.map((i) => [i.id, i.onHand]), mainBefore);
+});
+
+test("stock-takes only see locations and stock-takes of the request's site", async () => {
+  const { handle } = app();
+
+  // Annex cannot start a stock-take on main's location; main cannot start on annex-fridge.
+  assert.equal((await handle({ method: "POST", path: "/stocktakes", headers: ANNEX, body: { location: "dry" } })).status, 400);
+  assert.equal((await handle({ method: "POST", path: "/stocktakes", body: { location: "annex-fridge" } })).status, 400);
+
+  const [annexBatch] = await receiveAtAnnex(
+    handle,
+    [{ itemId: 1, qty: 5 }],
+    [{ lot: "AX-ST", expires: "2026-11-20", location: "annex-fridge" }],
+  );
+
+  const takeRes = await handle({ method: "POST", path: "/stocktakes", headers: ANNEX, body: { location: "annex-fridge" } });
+  assert.equal(takeRes.status, 201);
+  const takeId = takeRes.body.id;
+
+  // Main cannot count or finish annex's stock-take.
+  assert.equal((await handle({ method: "POST", path: `/stocktakes/${takeId}/counts`, body: { batchId: annexBatch.id, counted: 4 } })).status, 404);
+  assert.equal((await handle({ method: "POST", path: `/stocktakes/${takeId}/finish` })).status, 404);
+
+  // Annex cannot enter a main batch into its stock-take.
+  assert.equal((await handle({ method: "POST", path: `/stocktakes/${takeId}/counts`, headers: ANNEX, body: { batchId: 1, counted: 4 } })).status, 404);
+
+  // Annex counts its batch and finishes.
+  assert.equal((await handle({ method: "POST", path: `/stocktakes/${takeId}/counts`, headers: ANNEX, body: { batchId: annexBatch.id, counted: 4.5 } })).status, 200);
+  const finished = await handle({ method: "POST", path: `/stocktakes/${takeId}/finish`, headers: ANNEX });
+  assert.equal(finished.status, 200);
+  assert.deepEqual(finished.body.lines, [{ batchId: annexBatch.id, expected: 5, counted: 4.5, diff: -0.5 }]);
+});
+
+test("items, suppliers, recipes and dishes are shared across sites", async () => {
+  const { handle } = app();
+  const mainSuppliers = (await handle({ path: "/suppliers" })).body;
+  const annexSuppliers = (await handle({ path: "/suppliers", headers: ANNEX })).body;
